//! One-time tool: cuts `Sounds/Explosion.wav` from samples 0..=1830 of
//! `Sounds/MachineGun.wav` (design §4.6, per `Resources/Sounds/Explosion.txt`,
//! whose sole content is the literal text `MachineGun.wav: 0-1830`).
//!
//! `Explosion.wav` was lost from the original tree along with every other
//! asset in `Resources/Sounds/` beyond the four still present; this tool
//! regenerates it reproducibly from `MachineGun.wav` (8-bit unsigned mono
//! 22050 Hz PCM, source-map §3.9), so the cut is committed once and can be
//! regenerated byte-identically at any time.
//!
//! Usage: `cutwav [assets_dir]` (default `./assets`); reads
//! `<assets_dir>/Sounds/MachineGun.wav`, writes
//! `<assets_dir>/Sounds/Explosion.wav`.

use std::path::PathBuf;

/// Inclusive sample range cut from `MachineGun.wav`
/// (`Resources/Sounds/Explosion.txt`: `MachineGun.wav: 0-1830`).
const FIRST_SAMPLE: usize = 0;
const LAST_SAMPLE_INCLUSIVE: usize = 1830;

fn main() -> anyhow::Result<()> {
    let assets_dir: PathBuf = std::env::args()
        .nth(1)
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("assets"));

    let src_path = assets_dir.join("Sounds").join("MachineGun.wav");
    let dst_path = assets_dir.join("Sounds").join("Explosion.wav");

    let mut reader = hound::WavReader::open(&src_path)
        .map_err(|e| anyhow::anyhow!("cannot open {}: {e}", src_path.display()))?;
    let spec = reader.spec();
    anyhow::ensure!(
        spec.bits_per_sample == 8 && spec.channels == 1,
        "expected 8-bit mono PCM, found {:?}",
        spec
    );

    let samples: Vec<i8> = reader
        .samples::<i8>()
        .collect::<hound::Result<Vec<i8>>>()
        .map_err(|e| anyhow::anyhow!("decode error in {}: {e}", src_path.display()))?;
    anyhow::ensure!(
        samples.len() > LAST_SAMPLE_INCLUSIVE,
        "{} only has {} samples, need at least {}",
        src_path.display(),
        samples.len(),
        LAST_SAMPLE_INCLUSIVE + 1
    );
    let cut = &samples[FIRST_SAMPLE..=LAST_SAMPLE_INCLUSIVE];

    if let Some(parent) = dst_path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let mut writer = hound::WavWriter::create(&dst_path, spec)
        .map_err(|e| anyhow::anyhow!("cannot create {}: {e}", dst_path.display()))?;
    for &sample in cut {
        writer.write_sample(sample)?;
    }
    writer.finalize()?;

    println!(
        "wrote {} ({} samples, cut from {})",
        dst_path.display(),
        cut.len(),
        src_path.display()
    );
    Ok(())
}
